def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    components = []
    while cells:
        start = cells.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if (nr, nc) in cells:
                    cells.remove((nr, nc))
                    comp.add((nr, nc))
                    stack.append((nr, nc))
        components.append(comp)

    shape = max(components, key=len)
    r0 = min(r for r, c in shape)
    r1 = max(r for r, c in shape)
    c0 = min(c for r, c in shape)
    c1 = max(c for r, c in shape)
    anchor_r = (r1 - r0) // 2
    anchor_c = (c1 - c0) // 2

    markers = [p for comp in components if comp is not shape for p in comp]
    out = [row[:] for row in grid]

    for r, c in markers:
        out[r][c] = bg

    for mr, mc in markers:
        top, left = mr - anchor_r, mc - anchor_c
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                nr, nc = top + (r - r0), left + (c - c0)
                if 0 <= nr < h and 0 <= nc < w:
                    value = grid[r][c]
                    if value != bg:
                        out[nr][nc] = value

    return out
